package registry

import (
	"fmt"
	"os"
	"strings"
	"testing"
)

// fixtureSnapshot is the committed IANA snapshot (registry rule: versioned
// data, regenerated by scripts/regen_tls_parameters.sh, never hand-edited).
const fixtureSnapshot = "../../tests/fixtures/iana/tls-parameters-8.csv"

// fixtureMalformed is the hand-authored row-defect fixture for the Load
// error path; it is a test artifact, not a registry snapshot.
const fixtureMalformed = "../../tests/fixtures/iana/tls-parameters-8-malformed.csv"

// csvHeader carries the semantic column set of the IANA export; the
// committed snapshot extends it with IANA's trailing Comment column,
// which Load ignores.
const csvHeader = "Value,Description,DTLS-OK,Recommended,Reference"

func loadSnapshot(t *testing.T) map[uint32]GroupEntry {
	t.Helper()
	f, err := os.Open(fixtureSnapshot)
	if err != nil {
		t.Fatalf("open snapshot: %v", err)
	}
	defer f.Close() //nolint:errcheck
	m, err := Load(f)
	if err != nil {
		t.Fatalf("load snapshot: %v", err)
	}
	return m
}

// TestLoadFixtureSnapshot parses the committed IANA Supported Groups
// snapshot: the anchor codepoints and flag mapping (Y/N/D), and proof
// that IANA's N-M block-notation range rows are skipped, not entries.
func TestLoadFixtureSnapshot(t *testing.T) {
	m := loadSnapshot(t)
	// 101 data rows minus the 24 Unassigned/private-use N-M range rows.
	if len(m) != 77 {
		t.Errorf("Load(snapshot) returned %d entries, want 77", len(m))
	}
	if len(m) < 40 {
		t.Fatalf("expected the real IANA snapshot matrix, got %d entries", len(m))
	}

	cases := []struct {
		value       uint32
		name        string
		dtlsOK      bool
		recommended bool
		reference   string
	}{
		{4588, "X25519MLKEM768", true, true, "[RFC 10024]"},
		{4587, "SecP256r1MLKEM768", true, false, "[RFC 10024]"},
		{4589, "SecP384r1MLKEM1024", true, false, "[RFC 10024]"},
		{25497, "X25519Kyber768Draft00 (OBSOLETE)", true, false, "[draft-tls-westerbaan-xyber768d00-02]; [RFC 10024]"},
		{29, "x25519", true, true, "[RFC 9846]; [RFC 8422]"},
		{23, "secp256r1", true, true, "[RFC 8422]"},
		{0, "Reserved", false, false, "[RFC 8447]"},
	}
	for _, c := range cases {
		got, ok := m[c.value]
		if !ok {
			t.Errorf("snapshot missing codepoint %d", c.value)
			continue
		}
		want := GroupEntry{
			Value:       c.value,
			Name:        c.name,
			DTLSOK:      c.dtlsOK,
			Recommended: c.recommended,
			Reference:   c.reference,
		}
		if got != want {
			t.Errorf("snapshot entry %d = %+v, want %+v", c.value, got, want)
		}
	}

	for _, v := range []uint32{300, 510, 65500} { // inside IANA N-M range rows
		if _, ok := Lookup(m, v); ok {
			t.Errorf("range-row codepoint %d must not be an entry", v)
		}
	}
}

// TestLoadSkipsHeaderBlankComments checks the line-level grammar: the
// structural "Value,..." header line(s), blank lines and '#' comment
// lines never produce entries, whether trailing an IANA Comment column
// or not.
func TestLoadSkipsHeaderBlankComments(t *testing.T) {
	in := csvHeader + ",Comment\n" +
		"# provenance comment line, ignored\n" +
		"\n" +
		"29,x25519,Y,Y,[RFC 9846]; [RFC 8422],\n" +
		"\n" +
		"Value,Description,DTLS-OK,Recommended,Reference\n" +
		"23,secp256r1,Y,Y,[RFC 8422]\n"
	m, err := Load(strings.NewReader(in))
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if len(m) != 2 {
		t.Fatalf("Load = %d entries, want 2 (header/blank/comment lines skipped)", len(m))
	}
	if m[29].Name != "x25519" || !m[29].DTLSOK {
		t.Errorf("m[29] = %+v, want x25519 with DTLS-OK", m[29])
	}
	if m[23].Name != "secp256r1" || !m[23].DTLSOK {
		t.Errorf("m[23] = %+v, want secp256r1 with DTLS-OK", m[23])
	}
}

// TestLoadQuotedFields keeps quoted commas inside Description/Reference as
// a single field (46000 is synthetic — an in-memory snippet, not a table
// claim about the IANA matrix).
func TestLoadQuotedFields(t *testing.T) {
	in := csvHeader + "\n" +
		"46000,\"SecP256r1MLKEM512, quoted commas, intact\",Y,Y,\"[RFC 10024]; [RFC 9846]\"\n"
	m, err := Load(strings.NewReader(in))
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	got, ok := m[46000]
	if !ok {
		t.Fatalf("quoted row lost; m = %+v", m)
	}
	if got.Name != "SecP256r1MLKEM512, quoted commas, intact" {
		t.Errorf("Name = %q, want the quoted description intact", got.Name)
	}
	if got.Reference != "[RFC 10024]; [RFC 9846]" {
		t.Errorf("Reference = %q, want the quoted reference intact", got.Reference)
	}
}

// TestLoadSkipsRangeRows: IANA block notation ("N-M" — Unassigned /
// Reserved for Private Use swathes) is deliberately skipped, not a load
// error: a range carries no single-codepoint semantics.
func TestLoadSkipsRangeRows(t *testing.T) {
	in := csvHeader + ",Comment\n" +
		"42-100,Unassigned,,,,\n" +
		"508-511,Reserved for Private Use,,,[RFC 7919],\n" +
		"29,x25519,Y,Y,[RFC 9846]; [RFC 8422],\n"
	m, err := Load(strings.NewReader(in))
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if len(m) != 1 {
		t.Fatalf("Load = %d entries, want 1 (range rows skipped)", len(m))
	}
	if m[29].Name != "x25519" {
		t.Errorf("m[29].Name = %q, want x25519", m[29].Name)
	}
}

// TestLoadMalformed pins each defect class: Load aborts with the physical
// line number. Registry-reported defects are asserted exactly; defects
// raised by encoding/csv itself keep Go's wording (substring only).
func TestLoadMalformed(t *testing.T) {
	cases := []struct {
		name      string
		csv       string
		wantLine  int
		wantSub   string
		wantExact string
	}{
		{
			name:      "non-numeric value",
			csv:       csvHeader + "\n29,x25519,Y,Y,[RFC 9846]; [RFC 8422]\nnope,x25519,Y,Y,[RFC 8422]\n",
			wantLine:  3,
			wantSub:   `unsupported value "nope"`,
			wantExact: `registry: line 3: malformed row: unsupported value "nope" (want plain uint32 or N-M range)`,
		},
		{
			name:      "value over uint32",
			csv:       csvHeader + "\n4294967296,too-big,Y,Y,[RFC 1]\n",
			wantLine:  2,
			wantSub:   `unsupported value "4294967296"`,
			wantExact: `registry: line 2: malformed row: unsupported value "4294967296" (want plain uint32 or N-M range)`,
		},
		{
			name:      "row too short",
			csv:       csvHeader + "\n29,x25519\n",
			wantLine:  2,
			wantSub:   "need at least 5",
			wantExact: "registry: line 2: malformed row: got 2 fields, need at least 5",
		},
		{
			name:      "DTLS-OK flag",
			csv:       csvHeader + "\n29,x25519,Maybe,Y,[RFC 9846]\n",
			wantLine:  2,
			wantSub:   `DTLS-OK "Maybe"`,
			wantExact: `registry: line 2: malformed row: DTLS-OK "Maybe" (want Y, N or empty)`,
		},
		{
			name:      "Recommended flag",
			csv:       csvHeader + "\n23,secp256r1,Y,Maybe,[RFC 8422]\n",
			wantLine:  2,
			wantSub:   `Recommended "Maybe"`,
			wantExact: `registry: line 2: malformed row: Recommended "Maybe" (want Y, N, D or empty)`,
		},
		{
			// Go's csv wording; only the wrapper prefix and line are ours.
			name:     "unbalanced quotes",
			csv:      csvHeader + "\n21,\"SecP160K1,Y,N,[RFC 8422]\n",
			wantLine: 2,
			wantSub:  "quoted-field",
		},
	}
	for _, c := range cases {
		m, err := Load(strings.NewReader(c.csv))
		if err == nil {
			t.Errorf("%s: Load succeeded, want error (entries = %+v)", c.name, m)
			continue
		}
		if m != nil {
			t.Errorf("%s: Load returned entries on error, want nil", c.name)
		}
		if !strings.Contains(err.Error(), fmt.Sprintf("line %d", c.wantLine)) {
			t.Errorf("%s: error lacks line %d: %v", c.name, c.wantLine, err)
		}
		if !strings.Contains(err.Error(), c.wantSub) {
			t.Errorf("%s: error %q missing %q", c.name, err.Error(), c.wantSub)
		}
		if c.wantExact != "" && err.Error() != c.wantExact {
			t.Errorf("%s: error = %q, want %q", c.name, err.Error(), c.wantExact)
		}
	}
}

// TestLoadMalformedFixture drives the defect fixture file end to end:
// comments/blank line skipped, and the first malformed row (line 11,
// "bad-value") aborts the load with its physical line number.
func TestLoadMalformedFixtureAbortsAtLineNumber(t *testing.T) {
	f, err := os.Open(fixtureMalformed)
	if err != nil {
		t.Fatalf("open malformed fixture: %v", err)
	}
	defer f.Close() //nolint:errcheck
	m, err := Load(f)
	if err == nil {
		t.Fatalf("malformed fixture loaded, want abort (entries = %+v)", m)
	}
	if m != nil {
		t.Errorf("Load returned entries on error, want nil")
	}
	for _, frag := range []string{"line 11", `unsupported value "bad-value"`} {
		if !strings.Contains(err.Error(), frag) {
			t.Errorf("error %q missing %q", err.Error(), frag)
		}
	}
}

// TestLookup pins the map access contract: hit returns the entry, miss
// returns the zero entry, and a nil map is a miss (never a panic).
func TestLookup(t *testing.T) {
	m := map[uint32]GroupEntry{
		4588: {Value: 4588, Name: "X25519MLKEM768", DTLSOK: true, Recommended: true, Reference: "[RFC 10024]"},
	}
	got, ok := Lookup(m, 4588)
	if !ok || got != m[4588] {
		t.Errorf("Lookup(4588) = %+v, %v; want %+v, true", got, ok, m[4588])
	}
	got, ok = Lookup(m, 29)
	if ok || got != (GroupEntry{}) {
		t.Errorf("Lookup miss must return the zero entry; got %+v, %v", got, ok)
	}
	if _, ok := Lookup(nil, 29); ok {
		t.Errorf("Lookup on a nil map must report a miss")
	}
}
